mapper.select:
SELECT C.DOMAIN_ID , C.COMPANY_CD , C.TASK_ID , C.COMMENT_ID , C.COMMENT_CONTENT , C.COMMENT_RECEIVER_ID , EE.EMP_NM COMMENT_RECEIVER_NM , C.CREATE_USR , E.EMP_NM , CONVERT_TZ(C.CREATE_DT, '+00:00', '+09:00') AS CREATE_DT , CONVERT_TZ(C.UPDATE_DT, '+00:00', '+09:00') AS UPDATE_DT FROM COMMENT_MASTER C INNER JOIN EMP_MASTER E ON (E.EMAIL = C.CREATE_USR AND E.DOMAIN_ID = C.DOMAIN_ID AND E.COMPANY_CD = C.COMPANY_CD) LEFT JOIN EMP_MASTER EE ON (EE.EMAIL = C.COMMENT_RECEIVER_ID AND EE.DOMAIN_ID = C.DOMAIN_ID)
C.DOMAIN_ID = #{domainId} AND C.TASK_ID = #{taskId}
ORDER BY CREATE_DT

mapper.insert:
