	COMMENT_MASTER (
		DOMAIN_ID
		, COMPANY_CD
		, TASK_ID
		, COMMENT_CONTENT

		, COMMENT_RECEIVER_ID

		, UPDATE_USR
		, UPDATE_DT
		, CREATE_USR
		, CREATE_DT
	)
	VALUES (
		#{domainId}
		, #{companyCd}
		, #{taskId}
		, #{commentContent}

		, #{commentReceiverId}

		, #{email}
		, NOW()
		, #{email}
		, NOW()
	)

mapper.update:
UPDATE
	COMMENT_MASTER

	COMMENT_CONTENT = #{commentContent},
	UPDATE_DT = NOW()


	DOMAIN_ID = #{domainId}
	AND COMPANY_CD = #{companyCd}
	AND TASK_ID = #{taskId}
	AND COMMENT_ID = #{commentId}

